  values
    ('2bd561a2-02e0-4853-8494-76b4de9c9350', 'Aurora Medical Center', 'aurora-medical-center', 'A modern multi-specialty clinic offering connected appointments, preventive visits, secure records, patient messaging, and coordinated follow-up for everyday medical needs.', '#2563EB', '#0F172A', '#EFF6FF', true, now() - interval '100 days'),
    ('302079fb-0159-4279-97d6-7e4b3b57da9f', 'Evergreen Health Hub', 'evergreen-health-hub', 'A prevention-first health hub offering family medicine, wellness plans, secure records, patient messaging, and coordinated follow-up for long-term health goals.', '#059669', '#064E3B', '#ECFDF5', true, now() - interval '93 days'),
    ('9dee008a-8253-4146-aaca-bf2c24dd6a9c', 'LumaCare Institute', 'lumacare-institute', 'A diagnostic institute offering specialist visits, imaging review, secure records, patient messaging, and coordinated follow-up for complex medical questions.', '#7C3AED', '#4C1D95', '#F5F3FF', true, now() - interval '86 days'),
    ('cafdc490-ad1c-4775-9150-56ca3d522106', 'NovaPulse Clinic', 'novapulse-clinic', 'A specialist clinic offering cardiology, urgent reviews, secure records, patient messaging, and coordinated follow-up for faster decisions and safer care.', '#DC2626', '#450A0A', '#FEF2F2', true, now() - interval '79 days'),
    ('2b791e35-c12a-4519-ae28-b2bc1a723076', 'BluePeak Medical', 'bluepeak-medical', 'A patient-centered clinic offering chronic care, internal medicine, secure records, patient messaging, and coordinated follow-up for stable health routines.', '#0284C7', '#0C4A6E', '#E0F2FE', true, now() - interval '72 days'),
    ('2873e2ca-4694-4e99-bf92-3eda510e103b', 'Solace Women and Family Clinic', 'solace-women-family-clinic', 'A warm family clinic offering women’s health, pediatrics, secure records, patient messaging, and coordinated follow-up for patients at every life stage.', '#DB2777', '#831843', '#FCE7F3', true, now() - interval '65 days'),
    ('955fbf34-4c31-496d-8cbe-db1dd537c8b7', 'Atlas Sports Health', 'atlas-sports-health', 'A sports health clinic offering injury care, recovery plans, secure records, patient messaging, and coordinated follow-up for active patients and athletes.', '#EA580C', '#7C2D12', '#FFF7ED', true, now() - interval '58 days'),
