-- =========================================================
-- MEDSYNC DATABASE SEED
-- Run when you want to populate the database from scratch.
-- UUIDs are fixed random-looking values so the seed is re-runnable.
-- Demo password for inserted auth users: MedSyncDemo123!
-- =========================================================

begin;

create extension if not exists pgcrypto;

-- =========================================================
-- 1. USERS
-- =========================================================

on conflict (id) do update set email = excluded.email, raw_user_meta_data = excluded.raw_user_meta_data, updated_at = now();

-- =========================================================
-- 2. CLINICS
-- =========================================================

with upserted as (
  on conflict (slug) do update set
    name = excluded.name, description = excluded.description, primary_color = excluded.primary_color,
    secondary_color = excluded.secondary_color, soft_color = excluded.soft_color, is_active = true
  returning id, slug
)
on conflict (slug) do update set id = excluded.id;

-- =========================================================
-- 3. PROFILES
-- =========================================================

on conflict (id) do update set first_name=excluded.first_name,last_name=excluded.last_name,username=excluded.username,email=excluded.email,role=excluded.role,active_clinic_id=excluded.active_clinic_id,phone=excluded.phone,birth_date=excluded.birth_date,avatar_url=excluded.avatar_url,gender=excluded.gender,blood_type=excluded.blood_type,allergies=excluded.allergies,chronic_conditions=excluded.chronic_conditions,insurance_provider=excluded.insurance_provider,insurance_details=excluded.insurance_details,address=excluded.address,is_active=true,updated_at=now();

on conflict (code) do update set id=excluded.id;

on conflict (profile_id) do update set email_notifications=excluded.email_notifications, appointment_notifications=excluded.appointment_notifications, appointment_reminders=excluded.appointment_reminders, sms_notifications=excluded.sms_notifications, marketing_emails=excluded.marketing_emails, dark_mode=excluded.dark_mode, updated_at=now();

-- =========================================================
-- 4. CLINIC MEMBERSHIPS
-- =========================================================

on conflict (clinic_id,profile_id) do update set role=excluded.role,is_active=true,assigned_by=excluded.assigned_by;

-- =========================================================
-- 5. CLINIC DETAILS AND LOCATIONS
-- =========================================================

on conflict (clinic_id) do update set about=excluded.about,address=excluded.address,phone=excluded.phone,email=excluded.email,website=excluded.website,opening_hours=excluded.opening_hours,emergency_text=excluded.emergency_text,hero_title=excluded.hero_title,hero_subtitle=excluded.hero_subtitle,map_embed_url=excluded.map_embed_url,logo_url=excluded.logo_url,hero_image_url=excluded.hero_image_url,cover_image_url=excluded.cover_image_url,updated_at=now();

on conflict (id) do update set clinic_id=excluded.clinic_id,name=excluded.name,address=excluded.address,city=excluded.city,phone=excluded.phone,email=excluded.email,map_embed_url=excluded.map_embed_url,is_active=true;

on conflict (code) do update set id=excluded.id;

-- =========================================================
-- 6. DOCTORS
-- =========================================================

on conflict (id) do update set clinic_id=excluded.clinic_id,profile_id=excluded.profile_id,first_name=excluded.first_name,last_name=excluded.last_name,specialty=excluded.specialty,bio=excluded.bio,experience_years=excluded.experience_years,phone=excluded.phone,email=excluded.email,schedule_text=excluded.schedule_text,expertise=excluded.expertise,memberships=excluded.memberships,education=excluded.education,experience=excluded.experience,avatar_url=excluded.avatar_url,cover_image_url=excluded.cover_image_url,is_active=true;

on conflict (code) do update set id=excluded.id, profile_id=excluded.profile_id;

-- =========================================================
-- 7. CLINIC SERVICES
-- =========================================================

on conflict (id) do update set clinic_id=excluded.clinic_id,title=excluded.title,category=excluded.category,description=excluded.description,price_text=excluded.price_text,duration_minutes=excluded.duration_minutes,image_url=excluded.image_url,is_active=true;

on conflict (code) do update set id=excluded.id;

-- =========================================================
-- 8. DOCTOR DETAILS
-- =========================================================

on conflict (doctor_id,location_id) do nothing;

on conflict (doctor_id,service_id) do update set clinic_id=excluded.clinic_id;

on conflict (id) do update set doctor_id=excluded.doctor_id,location_id=excluded.location_id,weekday=excluded.weekday,start_time=excluded.start_time,end_time=excluded.end_time,slot_minutes=excluded.slot_minutes,is_active=true;

-- =========================================================
-- 9. TECHNOLOGIES
-- ========================================================= 

on conflict (id) do update set clinic_id=excluded.clinic_id,title=excluded.title,category=excluded.category,description=excluded.description,image_url=excluded.image_url,is_active=true;

-- =========================================================
-- 10. HEALTH TIPS
-- =========================================================

on conflict (id) do update set clinic_id=excluded.clinic_id,title=excluded.title,summary=excluded.summary,content=excluded.content,category=excluded.category,icon_name=excluded.icon_name,min_age=excluded.min_age,max_age=excluded.max_age,gender_target=excluded.gender_target,condition_tags=excluded.condition_tags,allergy_tags=excluded.allergy_tags,priority=excluded.priority,is_active=true;

-- =========================================================
-- 11. TRIAGE, APPOINTMENTS, NOTIFICATIONS, LOGS, MEDICAL DOCS
-- =========================================================

on conflict (id) do update set main_symptom=excluded.main_symptom,duration=excluded.duration,severity=excluded.severity,triage_level=excluded.triage_level,patient_note=excluded.patient_note,doctor_summary=excluded.doctor_summary,raw_draft=excluded.raw_draft;

on conflict (id) do update set clinic_id=excluded.clinic_id,location_id=excluded.location_id,doctor_id=excluded.doctor_id,service_id=excluded.service_id,patient_id=excluded.patient_id,appointment_date=excluded.appointment_date,start_time=excluded.start_time,end_time=excluded.end_time,status=excluded.status,reason=excluded.reason,notes=excluded.notes,ai_triage_summary=excluded.ai_triage_summary,ai_triage_level=excluded.ai_triage_level,ai_triage_patient_note=excluded.ai_triage_patient_note,triage_session_id=excluded.triage_session_id,checked_by=excluded.checked_by,checked_at=excluded.checked_at,updated_by=excluded.updated_by,updated_at=now();

on conflict (id) do update set new_status=excluded.new_status,message=excluded.message;

on conflict (id) do update set title=excluded.title,message=excluded.message,is_read=excluded.is_read,deep_link=excluded.deep_link,updated_at=now();

on conflict (appointment_id) do update set title=excluded.title,category=excluded.category,symptoms=excluded.symptoms,diagnosis=excluded.diagnosis,treatment_plan=excluded.treatment_plan,prescription=excluded.prescription,recommendations=excluded.recommendations,notes=excluded.notes,blood_pressure=excluded.blood_pressure,heart_rate=excluded.heart_rate,temperature=excluded.temperature,weight_kg=excluded.weight_kg,height_cm=excluded.height_cm,follow_up_date=excluded.follow_up_date,updated_at=now();

on conflict (id) do update set clinic_id=excluded.clinic_id,patient_id=excluded.patient_id,doctor_id=excluded.doctor_id,appointment_id=excluded.appointment_id,medical_record_id=excluded.medical_record_id,title=excluded.title,description=excluded.description,file_url=excluded.file_url,file_type=excluded.file_type,category=excluded.category,notes=excluded.notes,uploaded_by=excluded.uploaded_by,extracted_text=excluded.extracted_text,ai_summary=excluded.ai_summary,processing_status=excluded.processing_status,processed_at=excluded.processed_at,ai_image_audit=excluded.ai_image_audit,updated_at=now();

on conflict (appointment_id) do update set form_valid=excluded.form_valid,urgency_level=excluded.urgency_level,summary_for_doctor=excluded.summary_for_doctor,missing_information=excluded.missing_information,clarifying_questions=excluded.clarifying_questions,urgency_flags=excluded.urgency_flags,generated_by=excluded.generated_by,urgency_flags_structured=excluded.urgency_flags_structured,completion_score=excluded.completion_score,requires_manual_review=excluded.requires_manual_review,triage_recommendation=excluded.triage_recommendation,updated_at=now();

-- =========================================================
-- 12. CHATS
-- =========================================================

on conflict (clinic_id,patient_id,doctor_id) do update set last_message=excluded.last_message,last_message_at=excluded.last_message_at,patient_unread_count=excluded.patient_unread_count,doctor_unread_count=excluded.doctor_unread_count,updated_at=excluded.updated_at;

on conflict (id) do update set body=excluded.body,created_at=excluded.created_at;

on conflict (conversation_id,profile_id) do update set is_typing=excluded.is_typing,updated_at=excluded.updated_at;

-- =========================================================
-- REVIEWS, FEEDBACK, AUDIT LOGS
-- =========================================================

on conflict (id) do update set review_text=excluded.review_text,rating=excluded.rating,is_visible=true;

on conflict (profile_id,tip_id,reaction) do nothing;

on conflict (id) do update set action=excluded.action,metadata=excluded.metadata;

commit;